def build(rows_spec):
    g=[[5]*19 for _ in range(16)]
    for r,(zs,mode) in rows_spec.items():
        for j in zs: g[r][j]= 2 if mode=='z2' else 5 if mode=='z5' else 0
        for a,b in zip(zs,zs[1:]):
            for j in range(a+1,b): g[r][j]=2 if mode in ('fill','z5') else 0
    return g
